// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 amount) internal {
        vm.assume(amount > 0);
        vm.assume(c.currentBetLimit() == 0);
        try c.AdjustBetAmounts(amount) {} catch { return; }
        assertTrue(c.currentBetLimit() == amount);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }

    receive() external payable {}
}
